/**
 * What each certificate has earned and when it pays: the interest so far written into `accrued`, the interest over the
 * whole term into `interest`, and whatever the row left empty and could be worked out from the rest.
 *
 * STARTED WITH A ROW'S ID when a certificate is added or its principal, rate, term, start, cadence or maturity changes;
 * started with no id, once a day, it brings every live certificate up to today. Interest is the rate a year on the
 * principal: simple unless the certificate compounds, when it is added to the principal every month. It is counted from
 * the start to today, and never past the day it matures.
 *
 * `at_maturity` is the value the certificate has on the day it matures: the principal, grown at its rate over the whole
 * term when it compounds. It is always written, because Cash ahead walks it as the money coming back.
 *
 * WHAT IS WORKED OUT ONLY WHEN IT IS EMPTY, so a person's own word always wins. `ends` is the start and the term in
 * months. `payout` is one cycle's interest on a certificate that pays it out (not one that compounds). `next_payout` is
 * one cycle after the start, and never after the day it matures. Each amount is in the principal's currency.
 */
const DAY = 86_400_000;

const dayOf = (text) => {
  const m = typeof text === 'string' ? /^(\d{4})-(\d{2})-(\d{2})$/.exec(text) : null;
  return m ? Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) : null;
};

const written = (ms) => new Date(ms).toISOString().slice(0, 10);

const monthsOn = (text, n) => {
  const at = dayOf(text);
  if (at === null) return null;
  const d = new Date(at);
  const last = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + n + 1, 0)).getUTCDate();
  return written(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + n, Math.min(d.getUTCDate(), last)));
};

const CYCLE = { monthly: 1, quarterly: 3, yearly: 12 };

/** Interest on `principal` (minor units) over `days`, at `rate` percent a year; compounded monthly when asked. */
export function interestOver(principal, rate, days, compound) {
  if (!(days > 0) || !(rate > 0)) return 0;
  if (!compound) return Math.round((principal * rate * days) / 36_500);
  const months = days / 30.4375;
  return Math.round(principal * (Math.pow(1 + rate / 1200, months) - 1));
}

/** What to write onto one certificate to bring it level, as a patch; empty when it is level already. */
export function levelled(fields, today) {
  const money = (m) => m && typeof m.amount === 'number' && typeof m.currency === 'string';
  const same = (a, b) => money(a) && a.amount === b.amount && a.currency === b.currency;
  const out = {};
  const principal = fields.amount;
  if (!money(principal) || typeof fields.rate !== 'number') return out;
  const start = dayOf(fields.start);
  if (start === null) return out;
  let ends = fields.ends;
  if (!dayOf(ends) && typeof fields.term === 'number' && fields.term > 0) {
    ends = monthsOn(fields.start, Math.round(fields.term));
    out.ends = ends;
  }
  const compound = fields.roll === true;
  const step = CYCLE[fields.every];
  if (!money(fields.pays) && !compound && step) out.pays = { amount: interestOver(principal.amount, fields.rate, (step * 365) / 12, false), currency: principal.currency };
  if (!dayOf(fields.next_payout) && step && !compound) {
    const first = monthsOn(fields.start, step);
    out.next_payout = dayOf(ends) !== null && dayOf(first) > dayOf(ends) ? ends : first;
  }
  const stop = dayOf(ends);
  const until = Math.max(start, Math.min(dayOf(today), stop === null ? Infinity : stop));
  const accrued = { amount: interestOver(principal.amount, fields.rate, (until - start) / DAY, compound), currency: principal.currency };
  if (!same(fields.accrued, accrued)) out.accrued = accrued;
  if (stop !== null) {
    const whole = { amount: interestOver(principal.amount, fields.rate, (stop - start) / DAY, compound), currency: principal.currency };
    if (!same(fields.interest, whole)) out.interest = whole;
    /* WHAT COMES BACK ON THE DAY IT MATURES: the principal, and for one that compounds the interest grown into it. */
    const back = { amount: principal.amount + (compound ? whole.amount : 0), currency: principal.currency };
    if (!same(fields.at_maturity, back)) out.at_maturity = back;
  }
  return out;
}

export default async function run(ctx) {
  const id = ctx.input && ctx.input.id;
  const rows = id ? [await ctx.record.get(id)] : await ctx.record.list('certificates', { field: 'state', is: 'live' });
  const today = typeof ctx.today === 'function' ? ctx.today() : ctx.now().slice(0, 10);
  for (const row of rows) {
    if (!row) continue;
    const next = levelled(row.fields, today);
    if (Object.keys(next).length === 0) continue;
    ctx.update('certificates#' + row.seq, next, row.version);
  }
}

/**
 * Ask to move a certificate's next payout on when its payout is booked. Money in lands on the Ledger, and the certificate
 * still says the payout is due, so Cash ahead walks it a second time and Coming up reads it late.
 *
 * WHAT IT LOOKS FOR. Handed a Ledger line that came in and is cleared, `payoutOf` keeps the live certificates whose
 * payout is that amount in that currency, that pay into that account (or name none), and whose next payout is within
 * five days of the line. EXACTLY ONE IS THE CERTIFICATE; none or several and nothing is asked.
 *
 * IT ASKS, AND WRITES NOTHING BY ITSELF. One question on Decide, "Pay-out of Fenwick Bank is booked. Move its next
 * payout on to 14 December?", whose first answer carries the one write: `next_payout`, one cycle on, the day the host's
 * `ctx.cycle` walks (Cash ahead's own step). When that is past the day it matures, the answer marks it matured instead.
 * "Leave it" writes nothing.
 */

/** WHAT THE WALK READS OF A CERTIFICATE TO STEP IT, Cash ahead's own leg, written into the script as data. */
const LEG = { on: 'next_payout', every: { field: 'every', months: { monthly: 1, quarterly: 3, yearly: 12 } }, ends: 'ends' };

const MONTHS = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

const isDay = (d) => typeof d === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(d);

const words = (d) => {
  const m = isDay(d) ? /^(\d{4})-(\d{2})-(\d{2})$/.exec(d) : null;
  return m ? Number(m[3]) + ' ' + MONTHS[Number(m[2]) - 1] : String(d);
};

const apart = (a, b) => Math.abs(Date.parse(a + 'T00:00:00Z') - Date.parse(b + 'T00:00:00Z')) / 86_400_000;

export function payoutOf(line, certificates) {
  const f = line.fields;
  if (f.direction !== 'in' || f.state !== 'cleared' || !f.amount || !isDay(f.on)) return { nothing: 'The line is not money in that has cleared, so no certificate was looked for.' };
  const found = certificates.filter((c) => {
    const g = c.fields;
    if (g.state !== 'live' || !g.pays || g.pays.amount !== f.amount.amount || g.pays.currency !== f.amount.currency) return false;
    if (g.account && g.account !== f.account) return false;
    return isDay(g.next_payout) && apart(g.next_payout, f.on) <= 5;
  });
  if (found.length !== 1) return { nothing: found.length === 0 ? 'No certificate pays this amount about now, so nothing was asked.' : 'More than one certificate pays this amount about now, so nothing was asked.' };
  return { certificate: found[0] };
}

export function moveOn(certificate, next) {
  const g = certificate.fields;
  const name = String(g.bank ?? '').trim() || 'The certificate';
  if (!(isDay(next) && isDay(g.next_payout) && next > g.next_payout)) return { nothing: name + ' has no later payout day to move to, so nothing was asked.' };
  const matured = isDay(g.ends) && next > g.ends;
  return {
    ask: {
      cause: 'certificates.payout.' + certificate.spoken + ':' + g.next_payout,
      question: matured ? 'Its last payout is booked for ' + name + '. Mark the certificate matured?' : 'Payout of ' + name + ' is booked. Move its next payout on to ' + words(next) + '?',
      about: certificate.spoken,
      options: [
        matured
          ? { id: 'move', label: 'Mark it matured', because: 'It is no longer walked, so Cash ahead stops counting its payouts.', patches: [{ id: certificate.spoken, version: certificate.version, fields: { state: 'matured' } }] }
          : { id: 'move', label: 'Move it on', because: 'The next payout becomes ' + words(next) + ', so it is not read late or counted twice.', patches: [{ id: certificate.spoken, version: certificate.version, fields: { next_payout: next } }] },
        { id: 'leave', label: 'Leave it', because: 'The certificate keeps ' + words(g.next_payout) + ' as its next payout.' },
      ],
    },
  };
}

export default async function run(ctx) {
  const input = ctx.input && typeof ctx.input === 'object' ? ctx.input : {};
  const said = typeof input.line === 'string' ? input.line : '';
  if (!/^transactions#\d+$/.test(said) && !/^[0-9A-Za-z_-]+$/.test(said)) {
    ctx.log('The script was handed no line, so no certificate was looked for.');
    return null;
  }
  const row = await ctx.record.get(said);
  if (!row || row.register !== 'transactions' || !Number.isSafeInteger(row.seq)) return null;
  const rows = await ctx.record.list('certificates', { all: [{ field: 'state', is: 'live' }] });
  const certificates = rows.map((r) => ({ id: r.id, spoken: 'certificates#' + r.seq, version: r.version, fields: r.fields }));
  const found = payoutOf({ fields: row.fields }, certificates);
  if (found.nothing) {
    ctx.log(found.nothing);
    return null;
  }
  if (typeof ctx.cycle !== 'function') {
    ctx.log('The host hands no next day, so nothing was asked.');
    return null;
  }
  let next;
  try {
    next = await ctx.cycle(found.certificate.fields.next_payout, { leg: LEG, fields: found.certificate.fields });
  } catch {
    next = undefined;
  }
  const out = moveOn(found.certificate, next);
  if (out.nothing) {
    ctx.log(out.nothing);
    return null;
  }
  return { ask: out.ask };
}
